using System.IO;

using Shouldly;
using Xunit;

using Assimalign.Cohesion.Content.Binary;
using Assimalign.Cohesion.Content.Bmff;

namespace Assimalign.Cohesion.Content.Heif.Tests;

public sealed class HeifInspectionTraversalTests
{
    [Fact(DisplayName = "Cohesion Test [Content.Heif] - Inspection: ISO 23008-12 item properties use generic traversal")]
    public void Walk_HeifProfile_VisitsTypedItemProperties()
    {
        // Arrange: the HEIF fixture is generated by this repository's BMFF writer.
        using var source = new MemoryStream(HeifFixtures.Create("avif"));
        using var document = BmffDocument.Load(source, registry: HeifBoxRegistry.Register(BmffBoxRegistry.CreateBuilder()).Build());
        var count = 0;

        // Act
        BmffBoxWalker.Walk(document, (box, depth, path) =>
        {
            if (box is ImageSpatialExtentsBox) { count++; path[^1].ShouldBe(FourCC.Parse("ispe")); }
            return BmffWalkAction.Continue;
        });
        var properties = document.First<ItemPropertyContainerBox>();

        // Assert
        count.ShouldBe(1);
        properties.Children<ImageSpatialExtentsBox>().ShouldHaveSingleItem();
        document.First(FourCC.Parse("ispe")).ShouldBeOfType<ImageSpatialExtentsBox>();
        document.First<Av1ConfigurationBox>().IsLeaf.ShouldBeTrue();
    }
}
